<style>
.mdp-modern{--mdp-bg:#fff;--mdp-soft:#f6f7fb;--mdp-border:#e6e9f0;--mdp-text:#172033;--mdp-muted:#637086;--mdp-accent:#635bff;--mdp-tint:#eeedff;padding:20px 24px 32px;color:var(--mdp-text)}
.mdp-modern[data-theme="dark"]{--mdp-bg:#192130;--mdp-soft:#151c29;--mdp-border:#2c3546;--mdp-text:#eef0f8;--mdp-muted:#95a0b5;--mdp-accent:#a19cff;--mdp-tint:#2b2850}
.mdp-modern *{box-sizing:border-box}.mdp-modern h2,.mdp-modern h3,.mdp-modern h4,.mdp-modern strong{color:var(--mdp-text)}
.mdp-modern .mdp-heading{display:flex;align-items:center;justify-content:space-between;gap:24px;margin:0 0 24px}.mdp-modern .mdp-heading h2{font-size:26px;font-weight:700;letter-spacing:-.6px;margin:8px 0}.mdp-modern .mdp-heading p{margin:0;color:var(--mdp-muted);font-size:14px;line-height:1.6}
.mdp-modern .mdp-eyebrow{font-size:10px;letter-spacing:1.1px;text-transform:uppercase;font-weight:700;color:var(--mdp-muted)}
.mdp-modern .mdp-badge{display:inline-flex;align-items:center;flex-shrink:0;padding:7px 11px;border-radius:8px;background:var(--mdp-tint);color:var(--mdp-accent);font-size:11px;font-weight:700}
.mdp-modern .mdp-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:20px 0}.mdp-modern .mdp-metrics article{border:1px solid var(--mdp-border);border-radius:15px;background:var(--mdp-bg);padding:20px;min-width:0}.mdp-modern .mdp-metrics span{color:var(--mdp-muted);font-size:12px}.mdp-modern .mdp-metrics strong{display:block;font-size:clamp(18px,1.8vw,25px);font-weight:700;margin:10px 0;overflow-wrap:anywhere}.mdp-modern .mdp-metrics p{font-size:11px;color:var(--mdp-muted);margin:0}.mdp-modern .mdp-accent{color:var(--mdp-accent)!important}
.mdp-modern .mdp-panel{border:1px solid var(--mdp-border);border-radius:17px;background:var(--mdp-bg);overflow:hidden;margin:20px 0;box-shadow:0 3px 14px rgba(20,30,55,.025)}.mdp-modern .mdp-panel-heading{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:20px 22px;border-bottom:1px solid var(--mdp-border)}.mdp-modern .mdp-panel-heading h3{font-size:15px;font-weight:700;margin:4px 0}.mdp-modern .mdp-panel-heading p{font-size:12px;margin:5px 0 0;color:var(--mdp-muted)}
.mdp-modern .mdp-filter,.mdp-modern .mdp-actions{display:flex;align-items:flex-end;gap:10px;flex-wrap:wrap}.mdp-modern .mdp-filter label{font-size:11px;font-weight:600;color:var(--mdp-muted);margin:0}.mdp-modern .mdp-filter select{display:block;min-height:44px;min-width:125px;border:1px solid var(--mdp-border);border-radius:9px;background:var(--mdp-bg);color:var(--mdp-text);padding:8px 12px;margin-top:7px;font-size:13px}.mdp-modern select:focus-visible,.mdp-modern a:focus-visible,.mdp-modern button:focus-visible,.mdp-modern summary:focus-visible{outline:2px solid var(--mdp-accent);outline-offset:3px}
.mdp-modern .mdp-button{display:inline-flex;min-height:44px;align-items:center;justify-content:center;gap:8px;border:1px solid var(--mdp-border);border-radius:9px;background:var(--mdp-bg);color:var(--mdp-text);padding:10px 15px;font-size:12px;font-weight:600;text-decoration:none;line-height:1.4;transition:background .15s}.mdp-modern .mdp-button:hover{background:var(--mdp-soft)}.mdp-modern .mdp-primary{background:#635bff;color:#fff;border-color:#635bff}.mdp-modern .mdp-primary:hover{background:#5149e8;border-color:#5149e8;color:#fff}.mdp-modern button:disabled{opacity:.5;cursor:not-allowed}
.mdp-modern .mdp-toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:24px;flex-wrap:wrap}.mdp-modern .mdp-table-scroll{overflow-x:auto}.mdp-modern table{margin:0;width:100%;border-collapse:collapse;color:var(--mdp-text);background:var(--mdp-bg)}.mdp-modern .mdp-directory-table{min-width:780px}.mdp-modern .mdp-directory-table th{font-size:10px;text-transform:uppercase;letter-spacing:.6px;color:var(--mdp-muted);background:var(--mdp-soft);text-align:left;padding:13px 22px}.mdp-modern .mdp-directory-table td{padding:18px 22px;border-top:1px solid var(--mdp-border);font-size:13px}.mdp-modern .mdp-directory-table th:last-child,.mdp-modern .mdp-directory-table td:last-child{text-align:right}
.mdp-modern .mdp-empty{text-align:center!important;padding:50px 24px!important}.mdp-modern .mdp-empty i{font-size:28px;color:var(--mdp-accent);margin-bottom:15px}.mdp-modern .mdp-empty h4{font-size:16px;margin:0 0 8px}.mdp-modern .mdp-empty p{color:var(--mdp-muted);margin:0;font-size:13px}.mdp-modern .mdp-muted{color:var(--mdp-muted)}.mdp-modern .mdp-pagination{padding:18px 22px;border-top:1px solid var(--mdp-border)}.mdp-modern .pagination{margin:0}.mdp-modern .page-link{background:var(--mdp-bg);color:var(--mdp-text);border-color:var(--mdp-border)}.mdp-modern .page-item.active .page-link{background:#635bff;border-color:#635bff;color:#fff}
.mdp-modern .mdp-source-context{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));padding:20px 22px;gap:24px}.mdp-modern .mdp-source-context span,.mdp-modern .mdp-signatories span{display:block;font-size:11px;color:var(--mdp-muted)}.mdp-modern .mdp-source-context strong{display:block;margin-top:8px;font-size:13px}
.mdp-modern .mdp-notice{padding:16px 20px;border:1px solid;border-radius:12px;margin:20px 0;font-size:13px;line-height:1.6}.mdp-modern .mdp-notice ul{margin:8px 0 0;padding-left:20px}.mdp-modern .mdp-notice strong{color:inherit}.mdp-modern .mdp-danger{background:#fff1f2;border-color:#fecdd3;color:#9f1239}.mdp-modern .mdp-warning{background:#fffbeb;border-color:#fde68a;color:#92400e}.mdp-modern .mdp-warning-badge{background:#fffbeb;color:#92400e}.mdp-modern summary{cursor:pointer;font-weight:600}.mdp-modern[data-theme="dark"] .mdp-danger{background:#38202e;border-color:#663147;color:#fda4af}.mdp-modern[data-theme="dark"] .mdp-warning,.mdp-modern[data-theme="dark"] .mdp-warning-badge{background:#352d21;border-color:#625132;color:#fcd34d}
#mdp-report .mdp-table{min-width:1500px;font-size:11px}#mdp-report .mdp-table th,#mdp-report .mdp-table td{padding:12px 8px;border:1px solid var(--mdp-border);vertical-align:middle;line-height:1.5}#mdp-report .mdp-table thead th{text-align:center;background:var(--mdp-soft);font-size:10px;font-weight:700}#mdp-report .mdp-particulars{width:24%}#mdp-report .mdp-annual{width:9%}#mdp-report .mdp-activity{min-width:250px;overflow-wrap:anywhere}#mdp-report .mdp-number{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}#mdp-report .mdp-summary{font-weight:700;background:var(--mdp-soft)}#mdp-report .mdp-summary th{text-align:left}#mdp-report .mdp-grand-total{border-top:2px solid var(--mdp-border)}#mdp-report .mdp-bold{font-weight:700}
.mdp-modern .mdp-signatories{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));padding:24px;gap:25px}.mdp-modern .mdp-signatories strong{display:block;min-height:50px;padding:22px 0 8px;border-bottom:1px solid var(--mdp-border);font-size:13px;overflow-wrap:anywhere}.mdp-modern .mdp-signatories p{font-size:11px;color:var(--mdp-muted);margin:8px 0 0}.mdp-modern .mdp-footnote{font-size:11px;color:var(--mdp-muted);margin:12px 0;line-height:1.6}
@media(max-width:900px){.mdp-modern .mdp-signatories{grid-template-columns:repeat(2,minmax(0,1fr))}.mdp-modern .mdp-panel-heading{flex-wrap:wrap}.mdp-modern .mdp-heading{align-items:flex-start}.mdp-modern .mdp-heading h2{font-size:23px}}
@media(max-width:600px){.mdp-modern{padding:16px}.mdp-modern .mdp-heading{flex-direction:column;gap:12px}.mdp-modern .mdp-metrics,.mdp-modern .mdp-source-context,.mdp-modern .mdp-signatories{grid-template-columns:1fr}.mdp-modern .mdp-filter{width:100%}.mdp-modern .mdp-filter label{flex:1}.mdp-modern .mdp-filter select{width:100%}.mdp-modern .mdp-toolbar,.mdp-modern .mdp-actions{align-items:stretch}.mdp-modern .mdp-actions{width:100%}.mdp-modern .mdp-actions .mdp-button{flex:1}}
</style>
